package ch.piiwii.remote.tv;import android.app.*;import android.content.*;import android.media.*;import android.os.*;import android.view.KeyEvent;import java.net.*;import java.nio.charset.StandardCharsets;public class RemoteService extends Service{volatile boolean running=true;Thread d,c;AudioManager audio;@Override public void onCreate(){super.onCreate();audio=(AudioManager)getSystemService(AUDIO_SERVICE);if(Build.VERSION.SDK_INT>=26){NotificationChannel ch=new NotificationChannel("remote","PiiWii Remote",NotificationManager.IMPORTANCE_LOW);getSystemService(NotificationManager.class).createNotificationChannel(ch);}Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,"remote"):new Notification.Builder(this);startForeground(7,b.setContentTitle("PiiWii Remote TV").setContentText("Récepteur actif").setSmallIcon(android.R.drawable.ic_media_play).build());d=new Thread(this::discover);c=new Thread(this::commands);d.start();c.start();}private void discover(){try(DatagramSocket s=new DatagramSocket(45454)){byte[]b=new byte[256];while(running){DatagramPacket p=new DatagramPacket(b,b.length);s.receive(p);String m=new String(p.getData(),0,p.getLength(),StandardCharsets.UTF_8);if("PIIWII_DISCOVER".equals(m)){String n=Build.MODEL==null?"Android TV":Build.MODEL;byte[]r=("PIIWII_REMOTE|"+n+"|TV").getBytes(StandardCharsets.UTF_8);s.send(new DatagramPacket(r,r.length,p.getAddress(),p.getPort()));}}}catch(Exception ignored){}}private void commands(){try(DatagramSocket s=new DatagramSocket(45455)){byte[]b=new byte[256];while(running){DatagramPacket p=new DatagramPacket(b,b.length);s.receive(p);String m=new String(p.getData(),0,p.getLength(),StandardCharsets.UTF_8);if(m.startsWith("PIIWII_CMD|"))handle(m.substring(11));}}catch(Exception ignored){}}private void handle(String x){switch(x){case"VOL_UP":audio.adjustStreamVolume(AudioManager.STREAM_MUSIC,AudioManager.ADJUST_RAISE,AudioManager.FLAG_SHOW_UI);break;case"VOL_DOWN":audio.adjustStreamVolume(AudioManager.STREAM_MUSIC,AudioManager.ADJUST_LOWER,AudioManager.FLAG_SHOW_UI);break;case"MUTE":if(Build.VERSION.SDK_INT>=23)audio.adjustStreamVolume(AudioManager.STREAM_MUSIC,AudioManager.ADJUST_TOGGLE_MUTE,AudioManager.FLAG_SHOW_UI);break;case"PLAY_PAUSE":key(KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE);break;case"NEXT":key(KeyEvent.KEYCODE_MEDIA_NEXT);break;case"PREV":key(KeyEvent.KEYCODE_MEDIA_PREVIOUS);break;}}private void key(int k){audio.dispatchMediaKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,k));audio.dispatchMediaKeyEvent(new KeyEvent(KeyEvent.ACTION_UP,k));}@Override public int onStartCommand(Intent i,int f,int id){return START_STICKY;}@Override public android.os.IBinder onBind(Intent i){return null;}@Override public void onDestroy(){running=false;super.onDestroy();}}
